/* Individually reviewed user guidance. Scope: public atlas and existing technical descriptions.
   Each tuple: use/result KO, reading check KO, image focus KO, corresponding EN, related IDs.
   These are interpretation prompts, not new model capabilities or promised output variables. */
const rows={
 'rain-spatial':['강우가 유역 내 어디에 집중되는지 반영할 때 사용합니다. 유출 계산에 들어가는 격자별 강우의 공간분포를 이해할 수 있습니다.','관측소·레이더·격자 자료의 시간 간격, 단위와 계산 영역이 일치하는지 확인합니다.','관측자료가 계산격자의 강우 입력으로 이어지는 위치를 보세요. 색상은 강우 공간화의 개념이며 실제 강우량이 아닙니다.','Use this to represent where rainfall falls within a basin and understand the spatial forcing supplied to runoff calculations.','Check forcing intervals, units and spatial coverage against the model domain.','Follow the transfer from observations to grid-cell rainfall. Colors illustrate spatial allocation, not measured rainfall.', ['rain-methods','rain-summary']],
 'rain-methods':['관측소 강우를 격자로 배분할 때 Thiessen과 IDW 경로를 검토합니다. 배분 방법에 따라 달라지는 격자 강우를 비교하는 출발점입니다.','동일 관측기간과 관측소 구성을 사용해 배분 결과를 비교하고 입력 QA를 확인합니다.','공통 그림은 관측소에서 격자로 자료가 전달되는 관계를 설명합니다. 두 방법의 가중치나 우열을 비교한 결과는 아닙니다.','Review Thiessen and IDW when mapping station rainfall to model cells; the mapped rainfall is the quantity to compare.','Compare mapping results using the same stations and period, and review input QA.','This shared image shows station-to-grid mapping, not the weights or relative performance of the two methods.', ['rain-spatial','rain-qc']],
 'rain-qc':['고도 차이와 강우자료 품질을 함께 살펴볼 때 사용합니다. 보정된 공간 강우와 자료 점검 결과를 구분해 해석할 수 있습니다.','고도보정 전제와 원자료의 결측·품질 문제를 확인합니다. 점검을 통과한 자료도 관측 자체의 불확실성은 남습니다.','공간 배분과 자료 점검은 서로 다른 단계입니다. 참고 그림에서 입력자료가 격자로 연결되는 흐름을 보세요.','Use this to examine elevation-aware rainfall mapping together with input quality, distinguishing mapped rainfall from QA findings.','Review elevation-adjustment assumptions and missing or questionable source data; passing QA does not remove observational uncertainty.','Spatial mapping and input checking are different steps. Follow the connection from input data to model cells.', ['rain-methods','input-precheck']],
 'rain-summary':['모의기간의 강우자료가 충분한지 판단할 때 사용합니다. 관측·예측·결측 시간수를 통해 자료 구성이 결과 해석에 미치는 영향을 살펴볼 수 있습니다.','결측 시간수가 0인지, 예측자료가 어느 기간에 포함되는지 확인합니다. 이 집계는 결측 강우를 채워주지 않습니다.','세 유형의 기간을 나누어 집계하는 관계를 보세요. 시간수나 비율은 실제 실행 리포트에서 확인합니다.','Use the observed, forecast and missing-hour counts to judge rainfall coverage over the simulation period.','Check missing intervals and the forecast portion of the record. These counts do not fill missing rainfall.','Read the three interval categories; obtain actual durations or proportions from the run report.', ['run-report','rain-spatial']],
 'input-precheck':['계산 시작 전에 고쳐야 할 입력 문제를 찾는 데 활용합니다. 공간·시간·연결성 점검 결과로 실행 준비 상태를 판단합니다.','점검 대상과 오류·경고를 구분하고 수정 후 재확인합니다. 실행 준비 점검과 모의 결과 검증은 별도입니다.','원자료 → 정합성 검사 → 점검 결과의 순서를 보세요. 실제 입력 작성 화면은 아닙니다.','Use prechecks to identify input problems to fix before a run and assess spatial, temporal and connectivity readiness.','Distinguish errors from warnings, review check coverage and rerun checks after corrections; result validation is a separate step.','Follow source data, consistency checks and check results. This is not an input-editor screenshot.', ['inputstudio','output-integrity']],
 ga:['강우 중 토양으로 들어가는 물과 지표유출로 이어지는 초과량을 구분할 때 활용합니다. 토양 침투가 유출 생성에 어떤 역할을 하는지 이해할 수 있습니다.','토양 특성과 초기 수분상태를 함께 살펴봅니다. 침투량과 하류 도달 유량은 서로 다른 계산 단계의 양입니다.','지표의 강우, 토양으로 내려가는 침투, 습윤전선의 이동을 구분해 보세요.','Use this to distinguish soil infiltration from rainfall excess that contributes to surface runoff.','Review soil properties and initial moisture; infiltration and downstream discharge belong to different calculation stages.','Distinguish rainfall at the surface, downward infiltration and wetting-front movement.', ['runoff','et']],
 runoff:['강우에 대한 빠른 지표 반응과 토양층을 통한 유출을 함께 이해할 때 활용합니다. 각 경로의 물이 하천 유입으로 이어지는 관계를 알 수 있습니다.','토양 저장 변화와 유출 전달을 함께 해석합니다. 격자에서 생성된 유출을 하류 지점 유량과 바로 동일시하지 않습니다.','지표와 토양층의 유출 화살표가 하천 쪽으로 모이는 경로를 보세요.','Use this to understand surface and subsurface contributions and how they feed the river.','Interpret storage changes together with routing; runoff generated in a cell is not the same as discharge at a downstream gauge.','Follow the surface and soil-layer pathways toward the channel.', ['ga','kw-hill']],
 continuous:['여러 강우사상과 건조기간을 연속해서 해석할 때 활용합니다. 계절별 유출과 물수지에 이전 저장상태가 미치는 영향을 살펴볼 수 있습니다.','연속 입력기간과 초기상태를 확인하고, 계절별 물수지와 감수부를 함께 검토합니다.','비가 오는 시기와 마른 시기 사이에도 토양·저장상태가 이어지는 점을 보세요.','Use continuous simulation to examine seasonal runoff and water balance across wet and dry periods with inherited storage.','Check continuous forcing and initial states, then review seasonal balance and recession behavior together.','Notice how storage carries between rainy and dry periods.', ['warmup','wb']],
 et:['강우가 적은 기간의 토양수분 감소와 장기 물수지를 해석할 때 활용합니다. 증발산에 따른 저장량 변화를 이해할 수 있습니다.','기상 입력과 토양·식생 조건을 함께 확인합니다. 증발산 수요와 토양에 저장된 물의 관계를 살펴봅니다.','토양에 저장된 물이 식생과 지표를 거쳐 대기로 이동하는 부분을 보세요.','Use this to interpret soil-water depletion and evapotranspiration-related storage changes in continuous water balance.','Review meteorological, soil and vegetation conditions, including the relationship between evaporative demand and stored water.','Follow stored soil water returning to the atmosphere through vegetation and the surface.', ['continuous','ga']],
 snow:['눈으로 저장된 강수가 나중에 유출에 기여하는 유역을 해석할 때 활용합니다. 적설 축적과 융설 시점을 구분해 장기 유출을 읽을 수 있습니다.','강설·기온 입력과 대상 유역의 기상 조건을 확인합니다. 강설 발생 시점과 융설수 유출 시점을 구분합니다.','적설저장과 녹아서 흘러나오는 물의 경로를 보세요. 그림은 경사 효과의 크기를 정량적으로 나타내지 않습니다.','Use this to distinguish snow accumulation from later meltwater contributions to runoff.','Review snowfall, temperature and basin meteorology, separating snowfall timing from meltwater runoff timing.','Follow snow storage and meltwater pathways. The image does not quantify slope effects.', ['continuous','runoff']],
 warmup:['본 모의의 시작 상태가 결과를 좌우하는지 살펴볼 때 활용합니다. 초기상태 조정과 목표지점 오차·수렴 진단을 함께 확인할 수 있습니다.','반복이 끝났다는 사실뿐 아니라 목표유량 오차와 상태 변화가 충분히 안정되는지 검토합니다.','초기상태 조정 → 목표지점 평가 → 반복 조정의 연결을 보세요. 저장 상태를 단순히 복원하는 과정과 다릅니다.','Use warm-up to assess initial-state sensitivity and review target-flow discrepancy alongside state convergence.','Inspect remaining target-flow error and state changes, rather than treating termination as proof of stabilization.','Follow adjustment, target-site review and iteration; this is different from simply restoring a checkpoint.', ['hotstart','continuous']],
 hotstart:['긴 계산을 나누거나 저장된 상태에서 모의를 이어갈 때 활용합니다. 중단 전 상태와 이후 계산을 연결할 수 있습니다.','체크포인트의 격자·상태·시간과 재시작 조건이 맞는지 확인합니다. 초기상태의 적절성은 워밍업 등으로 별도 검토합니다.','저장된 상태가 다음 계산의 시작점으로 전달되는 연결을 보세요.','Use a saved checkpoint to resume a run or continue a simulation in stages.','Check grid, state and time consistency at restart; assess initial-state suitability separately through warm-up or other review.','Follow the saved state becoming the starting point for the next computation.', ['warmup','output-integrity']],
 dlayer:['강우 종료 후의 장기 감수부와 저유량을 설명하는 심부저장 기여를 검토할 때 활용하는 개발기능입니다.','심부 저장량, 지연 방출과 손실의 관계를 확인하고 관측 감수부와 비교합니다. 완전한 지하수유동 해석과는 구분합니다.','D층의 느린 저장·방출 경로를 보세요. 표시된 D층은 개발 중인 확장입니다.','This development feature supports examination of deeper storage contributions to recession and low flows.','Review deep storage, delayed release and losses against observed recession; distinguish this representation from a full groundwater-flow model.','Focus on slow storage and release in the D-layer, an extension in development.', ['river-infil','continuous']],
 'slope-separate':['사면과 하도의 지형 조건을 구분해 유출 전달을 구성할 때 활용합니다. 서로 다른 흐름 경로에 어떤 경사가 적용되는지 알 수 있습니다.','사면경사와 하도경사의 산정 기준·방향·단위를 각각 확인합니다. 하나의 경사를 모든 경로에 일괄 적용하지 않도록 검토합니다.','사면에서 하도로 이어지는 서로 다른 흐름 경로를 보세요. 경사값을 비교한 정량 도표는 아닙니다.','Use separate slopes to represent distinct hillslope and channel routing conditions.','Review the derivation, direction and units of each slope, and check that the intended slope is assigned to each pathway.','Identify the hillslope and channel pathways; the image is not a numerical comparison of slopes.', ['kw-hill','kw-river']],
 'kw-hill':['격자 사면에서 생긴 유출이 하천에 도달하는 과정을 해석할 때 활용합니다. 유출의 생성과 이동을 구분해 볼 수 있습니다.','사면 연결과 경사·조도 등 전달 조건을 확인합니다. 하천 수위에 의한 복잡한 배수위 해석과 적용 범위를 구분합니다.','사면에서 하천으로 물이 모이는 구간에 주목하세요. 공통 그림 중 사면 전달 부분에 해당합니다.','Use hillslope routing to examine how generated runoff moves toward the channel.','Check hillslope connectivity and routing conditions, and distinguish its scope from complex backwater hydraulics.','Focus on the hillslope-to-channel part of the shared routing illustration.', ['runoff','kw-river']],
 'kw-river':['하도로 모인 유량과 측방유입이 하류로 전달되는 과정을 해석할 때 활용합니다. 지점별 유량 변화의 전달 관계를 이해할 수 있습니다.','하도 길이·폭·경사·조도와 연결을 확인합니다. 동역학파에 의한 수위·유량 해석과 동일한 기능으로 보지 않습니다.','하천을 따라 하류로 향하는 경로를 보세요. 사면에서 발생하는 유출과 하도 전달을 구분합니다.','Use channel routing to examine downstream discharge propagation with lateral inflows.','Check channel geometry, slope, roughness and connectivity; distinguish this from dynamic-wave water-level and discharge analysis.','Focus on the downstream channel pathway, separate from hillslope runoff generation.', ['kw-hill','dwnet']],
 'river-infil':['하천수 일부가 심부저장으로 이동할 때 하천과 D층 물수지가 어떻게 연결되는지 검토하는 개발기능입니다.','침투가능량과 심부 저장여유의 제한을 함께 확인하고, 이동량이 두 영역의 물수지에 일관되게 반영되는지 살펴봅니다.','하천 바닥에서 심부저장으로 향하는 화살표를 보세요. 그림의 화살표 크기는 실제 침투량을 뜻하지 않습니다.','This development feature examines river-to-deep-storage transfers and their role in the two water balances.','Review infiltration capacity, available deep storage and consistent transfer accounting between the domains.','Follow the riverbed-to-storage arrow; its size does not represent an actual flux.', ['dlayer','wb']],
 channelbed:['DEM에 수중 하상이나 저수로 형상이 충분하지 않을 때 수리해석용 지형을 보완하는 데 활용하는 개발도구입니다.','보완에 사용한 중심선·단면 등 자료와 높이 기준을 확인합니다. 보완 지형은 측량 원자료와 구분해 검토합니다.','지형 표면과 추가로 표현해야 하는 하상·저수로 형상의 차이를 보세요.','This tool in development supports hydraulic terrain preparation where a DEM does not adequately represent the riverbed or low-flow channel.','Review supporting centerlines or cross sections and vertical references; distinguish supplemented terrain from original survey data.','Compare the terrain surface with the riverbed or low-flow geometry that requires supplementation.', ['dwnet','local-inertia']],
 wb:['계산에서 물의 유입·유출·저장 변화가 맞는지 확인할 때 활용합니다. 폐합오차로 물수지의 일관성을 점검할 수 있습니다.','같은 기간과 영역, 같은 단위로 각 항을 집계합니다. 작은 폐합오차만으로 관측유량 재현성이 입증되지는 않습니다.','유역 경계를 넘는 유입·유출과 내부 저장량 변화를 구분해 보세요.','Use closure residuals to check consistency among inflows, outflows and storage changes.','Use the same domain, period and units for all terms; a small residual does not establish agreement with observed discharge.','Distinguish boundary fluxes from changes in storage inside the watershed.', ['wb-1d2d','optimization']],
 'wb-1d2d':['하천에서 범람원으로 이동한 물이 두 계산 영역에 일관되게 반영되는지 확인하는 개발 검증 항목입니다.','동일 교환량이 반대 부호로 반영되는지 확인합니다. 교환량 일관성과 전체 유역의 물수지는 따로 평가합니다.','하천–범람원 경계의 양방향 화살표를 보세요. 물수지 판정 결과 자체를 그린 그림은 아닙니다.','Use this development check to examine consistent accounting of transfers between river and floodplain domains.','Confirm equal and opposite exchange entries; assess whole-basin balance separately.','Focus on the bidirectional boundary arrows, not on an implied water-balance pass result.', ['coupling','wb']],
 'run-report':['실행 결과를 다른 케이스와 비교하거나 문제 원인을 찾을 때 활용합니다. 입력조건·진단·물수지·경고·계산시간을 함께 읽을 수 있습니다.','실행모드와 초기상태가 의도한 조건인지 먼저 확인한 뒤 경고와 물수지를 살펴봅니다.','실행 조건을 기록하는 단계에 주목하세요. 출력 파일의 정상 여부를 점검하는 단계와 역할이 다릅니다.','Use the report to compare runs or investigate problems through their input context, diagnostics, balance, warnings and elapsed time.','Confirm run mode and initial states first, then review warnings and water balance.','Focus on recording run context, distinct from checking output-file integrity.', ['rain-summary','output-integrity']],
 'subbasin-report':['전체 유역 결과만으로 지역별 차이를 설명하기 어려울 때 활용합니다. 소유역별 강우·유출·상태를 나누어 비교할 수 있습니다.','소유역 경계와 평가 지점의 대응, 집계기간·단위를 확인합니다. 보고 단위 구분과 매개변수 보정은 별도입니다.','소유역 경계와 관측지점이 어떻게 대응하는지 보세요. 그림의 영역은 예시입니다.','Use subbasin reports to compare rainfall, runoff and states within the basin instead of relying only on basin totals.','Check boundaries, gauge correspondence, periods and units; reporting units do not perform parameter calibration.','Read the relationship between subbasin boundaries and evaluation points in the illustrative domain.', ['subcal','wb']],
 optimization:['목표지점의 관측유량을 더 잘 설명하는 매개변수 케이스를 검토하는 개발기능입니다. 여러 성능지표로 케이스 차이를 읽을 수 있습니다.','관측 품질과 평가기간을 확인하고 첨두·시점·총량·감수부를 함께 검토합니다. 보정기간 외 자료로도 재평가합니다.','관측자료와 매개변수 케이스가 같은 평가 단계로 모이는 흐름을 보세요. 최적화 성능을 입증한 수치 예시는 아닙니다.','This development feature compares parameter cases against observed discharge at a target site using multiple performance metrics.','Review observation quality and evaluation periods, inspect peaks, timing, volume and recession, and reassess outside the calibration period.','Follow observations and candidate parameters into a common evaluation; no optimization performance is demonstrated by the schematic.', ['subcal','wb']],
 subcal:['어느 소유역의 진단을 목표지점 보정에 연결할지 검토할 때 활용합니다. 진단 → 보정 → 재평가의 의사결정 과정을 지원합니다.','소유역 보고 결과와 목표지점의 관계를 확인합니다. 모든 소유역의 매개변수를 자동으로 찾아주는 기능으로 해석하지 않습니다.','소유역과 지점의 대응을 먼저 보세요. 보정 계산은 연결된 목표지점 보정 기능에서 별도로 설명합니다.','Use this development workflow to connect subbasin diagnostics with target-site calibration and reassessment.','Check how subbasin findings relate to the target site; do not assume automatic parameter targeting for every subbasin.','Start with subbasin-to-gauge correspondence; the linked calibration feature explains parameter-case evaluation.', ['subbasin-report','optimization']],
 'output-integrity':['결과 파일을 후처리나 Viewer로 넘기기 전에 활용합니다. 파일 생성·종료와 정의된 출력 요건이 충족되는지 판단할 수 있습니다.','오류상태와 필요한 결과항목을 확인합니다. 파일이 정상이라고 수문·수리 결과까지 타당한 것은 아닙니다.','결과 생성 이후 출력 요건을 점검하고 후처리로 전달하는 순서를 보세요.','Use integrity checks before handing outputs to postprocessing tools or a viewer.','Review error states and required outputs; valid files do not by themselves establish physically valid results.','Follow file creation, output checks and handover to postprocessing.', ['netcdf','run-report']],
 dwnet:['분기·합류가 있는 하천망의 수위와 유량을 함께 검토하는 수리 개발기능입니다. 하천 구간 간 연결된 흐름을 살펴볼 수 있습니다.','하천망·단면·경계조건과 관측 수위·유량을 함께 검토합니다. 적용 유역의 신뢰성 평가는 별도로 필요합니다.','지류와 본류, 분기 및 횡단면의 연결을 보세요. 화살표는 하천망의 개념적 방향입니다.','This hydraulic development feature examines connected water levels and discharges across branching river networks.','Review network geometry, cross sections, boundary conditions and observed levels or flows for the basin of interest.','Identify tributaries, the main river, branches and cross sections; arrows indicate conceptual connectivity.', ['junction','kw-river']],
 junction:['본류·지류의 합류 또는 흐름의 분기점에서 구간별 계산을 연결하는 개발기능입니다. 연결부의 흐름과 수리조건을 이해할 수 있습니다.','연결 방향과 연속조건을 확인하고 합류·분기 전후 구간을 함께 검토합니다.','공통 하천망 그림에서 여러 구간이 만나는 점과 갈라지는 점에 주목하세요.','This development feature links reach calculations at confluences and branching junctions.','Review connection direction and continuity together with the adjacent reaches.','Focus on the meeting and splitting points in the shared river-network illustration.', ['dwnet','structures']],
 structures:['수문·월류 등 구조물에 의한 유량 변화가 상·하류 계산에 미치는 영향을 검토하는 개발기능입니다.','구조물 형식·제원·수위 조건과 적용하는 유량 관계를 확인합니다. 실제 구조물의 운영자료와 함께 검토해야 합니다.','월류턱을 넘는 흐름과 수문 아래로 흐르는 물의 차이를 보세요. 실제 설계 제원을 나타낸 그림은 아닙니다.','This development feature examines how gate or overflow discharges affect upstream and downstream calculations.','Check structure type, dimensions, water levels and the applicable discharge relationship against the actual structure data.','Compare overflow across a crest with flow beneath a gate; dimensions are illustrative.', ['dwnet','dam-operation']],
 'dam-operation':['유입과 운영조건에 따라 방류·저류가 어떻게 구성되는지 검토하는 개발기능입니다. 저수지와 하류의 연결 관계를 읽을 수 있습니다.','대상 댐의 운영규칙·방류제약과 초기 저수상태를 별도로 확보하고 확인합니다. 공개 홈페이지는 실제 운영규칙을 제공하지 않습니다.','저수지의 유입·방류와 하류 연결을 보세요. 운영규칙이나 권장 방류량을 제시한 그림은 아닙니다.','This development feature examines releases and storage under specified inflows and operating conditions.','Obtain and review the applicable rules, release constraints and initial storage; this website does not supply actual operating rules.','Identify reservoir inflow, release and downstream connections, not recommended release values.', ['dam-forecast','dam-scenario']],
 'dam-forecast':['예측 유입을 반영한 방류 대안과 하류영향을 비교하는 운영지원 개발기능입니다. 대안별 영향을 검토하는 데 활용합니다.','예측의 불확실성, 저수지 상태와 하류 제약을 함께 확인합니다. 모의 대안은 실제 운영 승인과 구분합니다.','예측 유입, 저수지와 하류 평가구간을 함께 보세요. 방류 대안 간 차이를 검토하는 개념입니다.','This development feature supports comparison of release alternatives and downstream effects using forecast inflows.','Review forecast uncertainty, reservoir states and downstream constraints; scenario analysis is separate from operational authorization.','Read forecast inflows, reservoirs and downstream assessment reaches together.', ['dam-operation','dam-scenario']],
 'dam-scenario':['여러 댐의 운영 대안이나 재운영 조건을 같은 기준으로 비교하는 연구·평가용 개발기능입니다.','같은 유입조건·평가기간·목적지표를 사용해 대안을 비교합니다. 개별 댐의 효과와 댐군 전체 효과를 구분합니다.','개별 저수지보다 저수지망과 공통 하류 평가구간에 주목하세요.','This development feature supports research comparisons of multi-reservoir operating or reoperation scenarios.','Compare alternatives under common inflows, periods and objective metrics, separating individual-reservoir effects from system effects.','Focus on the reservoir network and common downstream assessment reach.', ['dam-forecast','dam-operation']],
 coupling:['하천에서 넘친 물이 범람원으로 이동하고 다시 돌아오는 관계를 검토할 때 활용합니다. 두 영역의 상호작용을 이해할 수 있습니다.','연결 경계·높이·수위와 교환량을 함께 확인합니다. 통제된 개발검증 결과와 실제 유역 적용성은 구분합니다.','하천에서 범람원으로 나가는 경로와 복귀 경로를 구분해 보세요.','Use this to understand overflow from a river and return flow from its floodplain across coupled domains.','Review connection geometry, levels and exchanged volumes; distinguish controlled validation from real-basin applicability.','Identify outward and returning flow paths across the river–floodplain boundary.', ['wb-1d2d','local-inertia']],
 'local-inertia':['범람원이 어디로 확산되고 어느 곳이 깊게 잠기는지 검토하는 2D 개발경로입니다. 침수심·유속 등 공간 결과를 해석하는 기반입니다.','지형·격자·경계조건과 계산 설정을 확인하고 대상 흐름에 대한 적용성을 검토합니다.','지형 위의 물과 계산격자를 보세요. 공간 구성 개념이며 Local Inertia 방정식이나 실제 침수예측을 보여주는 그림은 아닙니다.','This 2D development path supports examination of flood spread and spatial depth or velocity patterns.','Review terrain, grid, boundary conditions and numerical settings for the flow regime of interest.','Read the terrain, water and computational cells; the image does not show equations or an actual flood prediction.', ['fullswe','multires']],
 fullswe:['급변류 등 운동량을 더 완전하게 표현할 필요가 있는 관심 영역을 검토하는 특수 개발 옵션입니다.','기본 Local Inertia 경로와 목적·설정·검증 범위를 구분합니다. 더 복잡한 해석이 모든 조건에서 더 정확하다는 뜻은 아닙니다.','공통 그림은 2D 해석 공간만 설명합니다. Full SWE와 Local Inertia의 수치기법 차이를 나타내지는 않습니다.','This special development option addresses areas where more complete momentum representation is needed, including rapidly varying flows.','Distinguish its purpose, settings and validation scope from Local Inertia; greater complexity does not guarantee greater accuracy.','The shared picture shows only the 2D spatial setting, not differences between Full SWE and Local Inertia.', ['local-inertia','multires']],
 multires:['전체 영역의 계산비용을 고려하면서 관심구간을 세밀하게 표현할 때 검토하는 개발기능입니다.','기본격자와 Patch의 연결, 경계와 결과 일관성을 확인합니다. 격자를 세분화하는 효과는 원지형 자료와 함께 평가합니다.','기본격자 중 일부 영역을 확대해 더 작은 격자로 표현하는 관계를 보세요.','This development feature explores finer representation of selected areas while considering whole-domain computational cost.','Review base-grid and patch connections, boundaries and result consistency alongside source-terrain resolution.','Follow the selected base-grid area into the finer patch.', ['local-inertia','channelbed']],
 'flood-extras':['범람원 흐름에 직접강우·배수·구조물·추적자 영향을 함께 검토하는 통합 개발기능입니다.','사용할 구성요소의 지원·검증 범위를 각각 확인합니다. 모든 요소가 모든 설정에서 동일하게 지원된다고 가정하지 않습니다.','그림은 공통 범람원·격자 배경입니다. 강우·배수·추적자의 모든 구현이나 결과를 한 번에 나타내지는 않습니다.','This integrated development feature examines direct rainfall, drainage, structures and tracers within floodplain analysis.','Check support and validation for each selected component rather than assuming universal support across all configurations.','The shared picture shows the floodplain grid, not every extension or its outputs.', ['structures','dye']],
 'sed-hill':['사면에서 발생한 유사가 이동하거나 퇴적되는 경로를 검토하는 연구기능입니다. 물 유출과 유사유출을 구분해 볼 수 있습니다.','침식원·토양 조건과 운반능 가정을 확인하고 유사 관련 자료로 별도 평가합니다.','사면의 침식원에서 물을 따라 이동해 퇴적되는 순서를 보세요.','This research feature examines sediment generation, transport and deposition on hillslopes, separately from water runoff.','Review sediment sources, soil conditions and transport-capacity assumptions against sediment-specific evidence.','Follow hillslope erosion, transport by flow and downstream deposition.', ['sed-river','runoff']],
 'sed-river':['상류에서 유입한 유사가 하천 구간을 따라 이동·퇴적되는 양상을 검토하는 연구기능입니다.','상류 유사 입력과 하도 조건·운반능을 확인합니다. 사면의 유사 생성량과 하천 이송량을 구분합니다.','공통 그림 중 하천 내 이송·퇴적 구간에 주목하세요. 사면 침식 부분은 상류 공급 맥락입니다.','This research feature examines transport and deposition of incoming sediment along river reaches.','Review upstream sediment supply, channel conditions and transport capacity, distinguishing sediment production from river transport.','Focus on channel transport and deposition; hillslope erosion provides supply context in the shared illustration.', ['sed-hill','dwnet']],
 dye:['보존성 물질이 물의 흐름을 따라 언제·어디로 이동하는지 검토하는 연구기능입니다. 농도와 질량 이동을 해석합니다.','주입질량·시점·유량과 질량보존을 확인합니다. 반응·분해가 포함된 일반 수질예측과 구분합니다.','주입 위치와 하류의 관측 위치를 보세요. 색상은 이동 개념이며 실제 농도 등급이 아닙니다.','This research feature examines the timing and pathways of conservative transport through concentration and mass movement.','Review injected mass, timing, discharge and mass conservation; distinguish conservative transport from reactive water-quality prediction.','Identify injection and downstream observation locations; colors are not measured concentration classes.', ['wq','flood-extras']],
 wq:['현재 사용할 수 있는 수질계산의 범위를 확인하는 항목입니다. 질소·인·BOD 등의 수질 과정 모듈은 비활성 상태이며 재개발 후보입니다.','활성 수질 계산이나 결과출력을 기대하지 않도록 배포본의 기능 범위를 확인합니다. 보존성 추적자와도 구분합니다.','현재 사용 가능한 수질 결과로 오인할 수 있어 예시 결과 그림을 제공하지 않습니다.','Use this entry to understand availability: nitrogen, phosphorus, BOD and related water-quality processes are disabled and remain redevelopment candidates.','Check the package scope; do not expect active water-quality calculations or outputs, or confuse them with conservative tracers.','No example result is shown because it could imply an available water-quality calculation.', ['dye','estuary']],
 parallel:['큰 계산의 실행시간과 계산 자원 사용을 검토할 때 활용합니다. 단일 실행·OpenMP·MPI의 역할을 구분할 수 있습니다.','같은 입력에서 결과정합성과 실행시간을 함께 비교합니다. 코어 수 증가만으로 같은 비율의 속도 향상을 기대하지 않습니다.','작업을 나누고 결과를 모으는 구조를 보세요. 그림은 실제 성능 측정이나 속도 향상 수치가 아닙니다.','Use this to understand single-process, shared-memory and distributed-memory execution when considering runtime and resources.','Compare result consistency and elapsed time for the same inputs; additional cores need not yield proportional speedup.','Read task partitioning and combination; the image is not a performance benchmark.', ['output-integrity','netcdf']],
 netcdf:['계산 결과를 Viewer나 후처리 도구에서 읽을 수 있도록 시간·좌표·변수 구조를 이해할 때 활용합니다.','파일에 포함된 변수·단위·시간·좌표와 후처리 도구의 호환성을 확인합니다. 포함 변수는 계산 기능과 설정에 따릅니다.','계산 엔진의 결과가 파일을 거쳐 분석 도구로 전달되는 부분을 보세요.','Use this to understand the time, coordinate and variable structure used to transfer model outputs to analysis tools.','Check included variables, units, times, coordinates and tool compatibility; contents depend on the calculation path and settings.','Follow the engine-to-output-file-to-analysis-tool connection.', ['output-integrity','viewer']],
 viewer:['계산된 공간분포와 시계열을 함께 살펴볼 때 활용하는 결과 분석 프로그램입니다. 침수심·유속 등 출력의 위치와 시간 변화를 읽습니다.','입력 결과의 좌표·시간·변수와 계산 기능의 개발 상태를 확인합니다. 뷰어의 표시 기능은 계산 결과의 검증을 대신하지 않습니다.','프로그램 관계도에서 결과를 받아 분석하는 끝단에 주목하세요. 실제 FloodViewer 화면은 아닙니다.','Use this results-analysis program to inspect spatial and time-series outputs, including available flood depths and velocities.','Check output coordinates, times, variables and the maturity of the generating calculation; visualization does not replace validation.','Focus on the analysis end of the workflow; this is not a FloodViewer screenshot.', ['netcdf','river-viewer']],
 inputstudio:['여러 원자료를 하나의 모의 프로젝트 입력으로 정리하고 검사할 때 활용하는 개발도구입니다.','원자료 출처와 좌표·시간 기준, 엔진 입력과의 일치 여부를 확인합니다. 결과를 읽는 Viewer와 역할을 구분합니다.','자료 작성·검사가 계산 엔진보다 앞에 놓이는 흐름을 보세요. 실제 편집 화면은 아닙니다.','This tool in development organizes and checks source data as inputs to a simulation project.','Review source provenance, coordinate and time references, and engine compatibility; distinguish input preparation from result viewing.','Focus on preparation and checking before the engine; the image is not an editor screenshot.', ['input-precheck','viewer']],
 estuary:['하구의 종·연직 방향 염분 분포와 성층을 연구할 때 검토하는 별도 실험 모형입니다. 유역 유출 해석과 연결되는 연구 맥락을 이해할 수 있습니다.','상류 유입·조위·염분 조건과 연직 해상도를 확인합니다. Core의 확립된 기능이나 검증된 현장 예측으로 해석하지 않습니다.','하천수와 해수의 연직 분포를 x-z 단면에서 보세요. 평면 범람지도와 다른 단면입니다.','This separate experimental model studies longitudinal–vertical estuarine salinity and stratification.','Review upstream inflow, tides, salinity conditions and vertical resolution; distinguish the prototype from established Core functions or validated field forecasts.','Read the vertical freshwater–seawater distribution in an x-z section, not a plan-view flood map.', ['dye','dwnet']],
 'river-viewer':['1D 하천수리 결과를 종단면·횡단면·시계열로 읽기 위한 별도 개발 프로그램입니다. 구간별 수위와 유량을 비교하는 목적입니다.','현재 미공개 상태와 결과파일 호환성을 확인합니다. 계산 엔진과 뷰어는 별도 역할입니다.','종단면은 하천을 따른 변화, 횡단면은 단면 형상, 시계열은 시간 변화를 설명합니다. 실제 화면은 아닙니다.','This separately developed program is intended to compare 1D water levels and discharges through profiles, cross sections and time series.','Check its unpublished status and result-file compatibility; the solver and viewer serve different roles.','Profiles show along-river change, cross sections show geometry, and time series show temporal change; these are not screenshots.', ['dwnet','viewer']]
};
function get(id,lang){const row=rows[id];if(!row)throw Error('Missing user guidance: '+id);const offset=lang==='ko'?0:3;return {goal:row[offset],check:row[offset+1],figure:row[offset+2],related:row[6]};}
function validate(data){const assert=require('node:assert/strict');assert.equal(Object.keys(rows).length,data.items.length);for(const item of data.items){const row=rows[item.id];assert.equal(row?.length,7,item.id);for(const value of row.slice(0,6))assert.ok(typeof value==='string'&&value.trim(),item.id);assert.ok(row[6].length>=1&&row[6].every(id=>id!==item.id&&data.items.some(i=>i.id===id)),item.id+' related');}}
module.exports={rows,get,validate};
